          'git',
          [
            '-c',
            'core.autocrlf=false',
            '-c',
            'core.longpaths=true',
            'ls-files',
            '--error-unmatch',
            '--',
            relative(root, path),
          ],
          { cwd: root, encoding: 'utf8' },
        )
